using System.Text.Json;
using System.Text.Json.Nodes;
using SmartFactory.Platform.Api.Tests.Infrastructure;

namespace SmartFactory.Platform.Api.Tests.Contracts;

/// <summary>
/// The OpenAPI document generated by the running API must equal the committed copy in
/// <c>contracts/openapi/platform-api.v1.json</c>. An intentional API change is made visible in the pull request by
/// regenerating the file: <c>SF_UPDATE_CONTRACTS=1 dotnet test SmartFactory.slnx</c>.
/// </summary>
public sealed class OpenApiContractTests(NoDatabaseFactory factory) : IClassFixture<NoDatabaseFactory>
{
    private static readonly JsonSerializerOptions Pretty = new() { WriteIndented = true };

    [Fact]
    public async Task Generated_openapi_document_matches_the_committed_contract()
    {
        var json = await factory.CreateClient().GetStringAsync(new Uri("/openapi/v1.json", UriKind.Relative), TestContext.Current.CancellationToken);
        var generated = Normalise(json);

        if (Environment.GetEnvironmentVariable("SF_UPDATE_CONTRACTS") == "1")
        {
            Directory.CreateDirectory(Path.GetDirectoryName(RepositoryPaths.OpenApiContract)!);
            await File.WriteAllTextAsync(RepositoryPaths.OpenApiContract, generated + "\n", TestContext.Current.CancellationToken);
        }

        File.Exists(RepositoryPaths.OpenApiContract).Should().BeTrue("run SF_UPDATE_CONTRACTS=1 dotnet test once to create the contract");
        var committed = Normalise(await File.ReadAllTextAsync(RepositoryPaths.OpenApiContract, TestContext.Current.CancellationToken));

        generated.Should().Be(committed,
            "the API surface changed; if intended, regenerate with SF_UPDATE_CONTRACTS=1 dotnet test SmartFactory.slnx and commit contracts/openapi");
    }

    [Fact]
    public async Task Contract_states_the_content_boundaries()
    {
        var json = await factory.CreateClient().GetStringAsync(new Uri("/openapi/v1.json", UriKind.Relative), TestContext.Current.CancellationToken);

        json.Should().Contain("synthetic").And.Contain("Advisory-only").And.Contain("\"/api/assets/assets\"");
    }

    // Why normalise: the server URL depends on the test host; everything else must match byte for byte.
    private static string Normalise(string json)
    {
        var node = JsonNode.Parse(json)!.AsObject();
        node.Remove("servers");
        return node.ToJsonString(Pretty).ReplaceLineEndings("\n");
    }
}
